export interface ConnectorConfig {
  /** Trello API key from https://trello.com/app-key */
  trelloApiKey: string
  /** Trello API token (generated via OAuth or manual token generation) */
  trelloApiToken: string
  /** The Trello card ID to add the checklist to */
  cardId: string
  /** Optional custom fetch implementation for testing */
  fetch?: typeof fetch
}

export interface GoogleCalendarWebhookPayload {
  event: string
  event_id: string
  account_id: string
  attendees: Array<{ email: string }>
}

export interface TrelloChecklistResponse {
  id: string
  idBoard: string
  idCard: string
  name: string
  checkItems: Array<{
    id: string
    state: string
    name: string
    pos: number
  }>
}

export interface HandleResult {
  checklistId: string
  checkItemId: string
  checkItemName: string
}

async function handle(
  payload: GoogleCalendarWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.attendees || payload.attendees.length === 0) {
    throw new Error('No attendees found in the webhook payload')
  }

  const firstAttendee = payload.attendees[0]
  if (!firstAttendee.email) {
    throw new Error('First attendee is missing an email address')
  }

  if (!config.cardId) {
    throw new Error('Trello cardId is required in the connector configuration')
  }

  if (!config.trelloApiKey) {
    throw new Error('Trello API key (TRELLO_API_KEY) is required')
  }

  if (!config.trelloApiToken) {
    throw new Error('Trello API token (TRELLO_API_TOKEN) is required')
  }

  const attendeeEmail = firstAttendee.email

  // Build the request URL with query parameters for auth
  const url = new URL('https://api.trello.com/1/checklists')
  url.searchParams.set('key', config.trelloApiKey)
  url.searchParams.set('token', config.trelloApiToken)

  // Request body: create a new checklist named "Attendees" with the first check item
  const requestBody = {
    idCard: config.cardId,
    name: 'Attendees',
    checkItems: [
      {
        name: attendeeEmail
      }
    ]
  }

  const response = await fetchImpl(url.toString(), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(requestBody)
  })

  if (!response.ok) {
    throw new Error(
      `Trello API request failed: ${response.status} ${response.statusText} for POST ${url.pathname}`
    )
  }

  const data = (await response.json()) as TrelloChecklistResponse

  if (!data.checkItems || data.checkItems.length === 0) {
    throw new Error('Trello API returned a checklist with no check items')
  }

  const createdCheckItem = data.checkItems[0]

  return {
    checklistId: data.id,
    checkItemId: createdCheckItem.id,
    checkItemName: createdCheckItem.name
  }
}

